import * as jsoncommon from '../../../common';

/**
 * Entity On Death (minecraft:on_death)
 * Adds a trigger to call on this entity's death.
 */
export default interface MinecraftOnDeath {

  /**
   * @remarks
   * The event to run when the conditions for this trigger are 
   * met.
   */
  event?: string;

  /**
   * @remarks
   * Filters allow data objects to specify test criteria which allows
   * their use. Filters can be defined by a single object of type
   * (Filter Test), an array of tests, collection groups, or a
   * combination of these objects.
   */
  filters?: MinecraftOnDeathFilters;

  /**
   * @remarks
   * The target of the event.
   */
  target?: string;

}


/**
 * Filters (filters)
 */
export interface MinecraftOnDeathFilters {

  /**
   * @remarks
   * The domain the test should be performed in.
   */
  domain?: object;

  /**
   * @remarks
   * The comparison to apply with 'value'.
   */
  operator?: object;

  /**
   * @remarks
   * The subject of this filter test.
   */
  subject?: object;

  /**
   * @remarks
   * The name of the test to apply.
   */
  test: string;

  /**
   * @remarks
   * The value being compared with the test.
   */
  value?: object;

}


export enum MinecraftOnDeathTarget {
  baby = `baby`,
  block = `block`,
  damager = `damager`,
  holder = `holder`,
  item = `item`,
  other = `other`,
  parent = `parent`,
  player = `player`,
  self = `self`,
  target = `target`
}